82	/*
83	 * hb_buffer_t
84	 */
85	
86	struct hb_buffer_t
87	{
88	  hb_object_header_t header;
89	  ASSERT_POD ();
90	
91	  /* Information about how the text in the buffer should be treated */
92	  hb_unicode_funcs_t *unicode; /* Unicode functions */
93	  hb_buffer_flags_t flags; /* BOT / EOT / etc. */
94	  hb_buffer_cluster_level_t cluster_level;
95	  hb_codepoint_t replacement; /* U+FFFD or something else. */
96	  hb_codepoint_t invisible; /* 0 or something else. */
97	  hb_buffer_scratch_flags_t scratch_flags; /* Have space-fallback, etc. */
98	  unsigned int max_len; /* Maximum allowed len. */
99	  int max_ops; /* Maximum allowed operations. */
100	
101	  /* Buffer contents */
102	  hb_buffer_content_type_t content_type;
103	  hb_segment_properties_t props; /* Script, language, direction */
104	
105	  bool successful; /* Allocations successful */
106	  bool have_output; /* Whether we have an output buffer going on */
107	  bool have_positions; /* Whether we have positions */
108	
109	  unsigned int idx; /* Cursor into ->info and ->pos arrays */
110	  unsigned int len; /* Length of ->info and ->pos arrays */
111	  unsigned int out_len; /* Length of ->out array if have_output */
112	
113	  unsigned int allocated; /* Length of allocated arrays */
114	  hb_glyph_info_t     *info;
115	  hb_glyph_info_t     *out_info;
116	  hb_glyph_position_t *pos;
117	
118	  unsigned int serial;
119	
120	  /* Text before / after the main buffer contents.
121	   * Always in Unicode, and ordered outward.
122	   * Index 0 is for "pre-context", 1 for "post-context". */
123	  enum { CONTEXT_LENGTH = 5 };
124	  hb_codepoint_t context[2][CONTEXT_LENGTH];
125	  unsigned int context_len[2];
126	
127	  /* Debugging API */
128	  hb_buffer_message_func_t message_func;
129	  void *message_data;
130	  hb_destroy_func_t message_destroy;
131	
132	  /* Internal debugging. */
133	  /* The bits here reflect current allocations of the bytes in glyph_info_t's var1 and var2. */
134	#ifndef HB_NDEBUG
135	  uint8_t allocated_var_bits;
136	#endif
137	
138	
139	  /* Methods */
140	
141	  inline void allocate_var (unsigned int start, unsigned int count)
142	  {
143	#ifndef HB_NDEBUG
144	    unsigned int end = start + count;
145	    assert (end <= 8);
146	    unsigned int bits = (1u<<end) - (1u<<start);
147	    assert (0 == (allocated_var_bits & bits));
148	    allocated_var_bits |= bits;
149	#endif
150	  }
151	  inline void deallocate_var (unsigned int start, unsigned int count)
152	  {
153	#ifndef HB_NDEBUG
154	    unsigned int end = start + count;
155	    assert (end <= 8);
156	    unsigned int bits = (1u<<end) - (1u<<start);
157	    assert (bits == (allocated_var_bits & bits));
158	    allocated_var_bits &= ~bits;
159	#endif
160	  }
161	  inline void assert_var (unsigned int start, unsigned int count)
162	  {
163	#ifndef HB_NDEBUG
164	    unsigned int end = start + count;
165	    assert (end <= 8);
166	    unsigned int bits = (1u<<end) - (1u<<start);
167	    assert (bits == (allocated_var_bits & bits));
168	#endif
169	  }
170	  inline void deallocate_var_all (void)
171	  {
172	#ifndef HB_NDEBUG
173	    allocated_var_bits = 0;
174	#endif
175	  }
176	
177	  inline hb_glyph_info_t &cur (unsigned int i = 0) { return info[idx + i]; }
178	  inline hb_glyph_info_t cur (unsigned int i = 0) const { return info[idx + i]; }
179	
180	  inline hb_glyph_position_t &cur_pos (unsigned int i = 0) { return pos[idx + i]; }
181	  inline hb_glyph_position_t cur_pos (unsigned int i = 0) const { return pos[idx + i]; }
182	
183	  inline hb_glyph_info_t &prev (void) { return out_info[out_len ? out_len - 1 : 0]; }
184	  inline hb_glyph_info_t prev (void) const { return out_info[out_len ? out_len - 1 : 0]; }
185	
186	  inline bool has_separate_output (void) const { return info != out_info; }
187	
188	
189	  HB_INTERNAL void reset (void);
190	  HB_INTERNAL void clear (void);
191	
192	  inline unsigned int backtrack_len (void) const
193	  { return have_output? out_len : idx; }
194	  inline unsigned int lookahead_len (void) const
195	  { return len - idx; }
196	  inline unsigned int next_serial (void) { return serial++; }
197	
198	  HB_INTERNAL void add (hb_codepoint_t  codepoint,
199				unsigned int    cluster);
200	  HB_INTERNAL void add_info (const hb_glyph_info_t &glyph_info);
201	
202	  HB_INTERNAL void reverse_range (unsigned int start, unsigned int end);
203	  HB_INTERNAL void reverse (void);
204	  HB_INTERNAL void reverse_clusters (void);
205	  HB_INTERNAL void guess_segment_properties (void);
206	
207	  HB_INTERNAL void swap_buffers (void);
208	  HB_INTERNAL void remove_output (void);
209	  HB_INTERNAL void clear_output (void);
210	  HB_INTERNAL void clear_positions (void);
211	
212	  HB_INTERNAL void replace_glyphs (unsigned int num_in,
213					   unsigned int num_out,
214					   const hb_codepoint_t *glyph_data);
215	
216	  inline void replace_glyph (hb_codepoint_t glyph_index)
217	  {
218	    if (unlikely (out_info != info || out_len != idx)) {
219	      if (unlikely (!make_room_for (1, 1))) return;
220	      out_info[out_len] = info[idx];
221	    }
222	    out_info[out_len].codepoint = glyph_index;
223	
224	    idx++;
225	    out_len++;
226	  }
227	  /* Makes a copy of the glyph at idx to output and replace glyph_index */
228	  inline hb_glyph_info_t & output_glyph (hb_codepoint_t glyph_index)
229	  {
230	    if (unlikely (!make_room_for (0, 1))) return Crap(hb_glyph_info_t);
231	
232	    out_info[out_len] = info[idx];
233	    out_info[out_len].codepoint = glyph_index;
234	
235	    out_len++;
236	
237	    return out_info[out_len - 1];
238	  }
239	  inline void output_info (const hb_glyph_info_t &glyph_info)
240	  {
241	    if (unlikely (!make_room_for (0, 1))) return;
242	
243	    out_info[out_len] = glyph_info;
244	
245	    out_len++;
246	  }
247	  /* Copies glyph at idx to output but doesn't advance idx */
248	  inline void copy_glyph (void)
249	  {
250	    if (unlikely (!make_room_for (0, 1))) return;
251	
252	    out_info[out_len] = info[idx];
253	
254	    out_len++;
255	  }
256	  /* Copies glyph at idx to output and advance idx.
257	   * If there's no output, just advance idx. */
258	  inline void
259	  next_glyph (void)
260	  {
261	    if (have_output)
262	    {
263	      if (out_info != info || out_len != idx)
264	      {
265		if (unlikely (!make_room_for (1, 1))) return;
266		out_info[out_len] = info[idx];
267	      }
268	      out_len++;
269	    }
270	
271	    idx++;
272	  }
273	  /* Copies n glyphs at idx to output and advance idx.
274	   * If there's no output, just advance idx. */
275	  inline void
276	  next_glyphs (unsigned int n)
277	  {
278	    if (have_output)
279	    {
280	      if (out_info != info || out_len != idx)
281	      {
282		if (unlikely (!make_room_for (n, n))) return;
283		memmove (out_info + out_len, info + idx, n * sizeof (out_info[0]));
284	      }
285	      out_len += n;
286	    }
287	
288	    idx += n;
289	  }
290	  /* Advance idx without copying to output. */
291	  inline void skip_glyph (void)
292	  {
293	    idx++;
294	  }
295	  inline void reset_masks (hb_mask_t mask)
296	  {
297	    for (unsigned int j = 0; j < len; j++)
298	      info[j].mask = mask;
299	  }
300	  inline void add_masks (hb_mask_t mask)
301	  {
302	    for (unsigned int j = 0; j < len; j++)
303	      info[j].mask |= mask;
304	  }
305	  HB_INTERNAL void set_masks (hb_mask_t value, hb_mask_t mask,
306				      unsigned int cluster_start, unsigned int cluster_end);
307	
308	  inline void merge_clusters (unsigned int start, unsigned int end)
309	  {
310	    if (end - start < 2)
311	      return;
312	    merge_clusters_impl (start, end);
313	  }
314	  HB_INTERNAL void merge_clusters_impl (unsigned int start, unsigned int end);
315	  HB_INTERNAL void merge_out_clusters (unsigned int start, unsigned int end);
316	  /* Merge clusters for deleting current glyph, and skip it. */
317	  HB_INTERNAL void delete_glyph (void);
318	
319	  inline void unsafe_to_break (unsigned int start,
320				       unsigned int end)
321	  {
322	    if (end - start < 2)
323	      return;
324	    unsafe_to_break_impl (start, end);
325	  }
326	  HB_INTERNAL void unsafe_to_break_impl (unsigned int start, unsigned int end);
327	  HB_INTERNAL void unsafe_to_break_from_outbuffer (unsigned int start, unsigned int end);
328	
329	
330	  /* Internal methods */
331	  HB_INTERNAL bool move_to (unsigned int i); /* i is output-buffer index. */
332	
333	  HB_INTERNAL bool enlarge (unsigned int size);
334	
335	  inline bool ensure (unsigned int size)
336	  { return likely (!size || size < allocated) ? true : enlarge (size); }
337	
338	  inline bool ensure_inplace (unsigned int size)
339	  { return likely (!size || size < allocated); }
340	
341	  HB_INTERNAL bool make_room_for (unsigned int num_in, unsigned int num_out);
342	  HB_INTERNAL bool shift_forward (unsigned int count);
343	
344	  typedef long scratch_buffer_t;
345	  HB_INTERNAL scratch_buffer_t *get_scratch_buffer (unsigned int *size);
346	
347	  inline void clear_context (unsigned int side) { context_len[side] = 0; }
348	
349	  HB_INTERNAL void sort (unsigned int start, unsigned int end, int(*compar)(const hb_glyph_info_t *, const hb_glyph_info_t *));
350	
351	  inline bool messaging (void) { return unlikely (message_func); }
352	  inline bool message (hb_font_t *font, const char *fmt, ...) HB_PRINTF_FUNC(3, 4)
353	  {
354	    if (!messaging ())
355	      return true;
356	    va_list ap;
357	    va_start (ap, fmt);
358	    bool ret = message_impl (font, fmt, ap);
359	    va_end (ap);
360	    return ret;
361	  }
362	  HB_INTERNAL bool message_impl (hb_font_t *font, const char *fmt, va_list ap) HB_PRINTF_FUNC(3, 0);
363	
364	  static inline void
365	  set_cluster (hb_glyph_info_t &inf, unsigned int cluster, unsigned int mask = 0)
366	  {
367	    if (inf.cluster != cluster)
368	    {
369	      if (mask & HB_GLYPH_FLAG_UNSAFE_TO_BREAK)
370		inf.mask |= HB_GLYPH_FLAG_UNSAFE_TO_BREAK;
371	      else
372		inf.mask &= ~HB_GLYPH_FLAG_UNSAFE_TO_BREAK;
373	    }
374	    inf.cluster = cluster;
375	  }
376	
377	  inline int
378	  _unsafe_to_break_find_min_cluster (const hb_glyph_info_t *infos,
379					     unsigned int start, unsigned int end,
380					     unsigned int cluster) const
381	  {
382	    for (unsigned int i = start; i < end; i++)
383	      cluster = MIN<unsigned int> (cluster, infos[i].cluster);
384	    return cluster;
385	  }
386	  inline void
387	  _unsafe_to_break_set_mask (hb_glyph_info_t *infos,
388				     unsigned int start, unsigned int end,
389				     unsigned int cluster)
390	  {
391	    for (unsigned int i = start; i < end; i++)
392	      if (cluster != infos[i].cluster)
393	      {
394		scratch_flags |= HB_BUFFER_SCRATCH_FLAG_HAS_UNSAFE_TO_BREAK;
395		infos[i].mask |= HB_GLYPH_FLAG_UNSAFE_TO_BREAK;
396	      }
397	  }
398	
399	  inline void
400	  unsafe_to_break_all (void)
401	  {
402	    unsafe_to_break_impl (0, len);
403	  }
404	  inline void
405	  safe_to_break_all (void)
406	  {
407	    for (unsigned int i = 0; i < len; i++)
408	      info[i].mask &= ~HB_GLYPH_FLAG_UNSAFE_TO_BREAK;
409	  }
410	};
411	DECLARE_NULL_INSTANCE (hb_buffer_t);
412	
413	
414	/* Loop over clusters. Duplicated in foreach_syllable(). */
415	#define foreach_cluster(buffer, start, end) \
416	  for (unsigned int \
417	       _count = buffer->len, \
418	       start = 0, end = _count ? _next_cluster (buffer, 0) : 0; \
419	       start < _count; \
420	       start = end, end = _next_cluster (buffer, start))
421	
422	static inline unsigned int
423	_next_cluster (hb_buffer_t *buffer, unsigned int start)
424	{
425	  hb_glyph_info_t *info = buffer->info;
426	  unsigned int count = buffer->len;
427	
428	  unsigned int cluster = info[start].cluster;
429	  while (++start < count && cluster == info[start].cluster)
430	    ;
431	
432	  return start;
433	}
434	
435	
436	#define HB_BUFFER_XALLOCATE_VAR(b, func, var) \
437	  b->func (offsetof (hb_glyph_info_t, var) - offsetof(hb_glyph_info_t, var1), \
438		   sizeof (b->info[0].var))
439	#define HB_BUFFER_ALLOCATE_VAR(b, var)		HB_BUFFER_XALLOCATE_VAR (b, allocate_var,   var ())
440	#define HB_BUFFER_DEALLOCATE_VAR(b, var)	HB_BUFFER_XALLOCATE_VAR (b, deallocate_var, var ())
441	#define HB_BUFFER_ASSERT_VAR(b, var)		HB_BUFFER_XALLOCATE_VAR (b, assert_var,     var ())
442	
443	
444	#endif /* HB_BUFFER_HH */
